// Isolated before/candidate kernels use the real dispatcher and common emitters.
mod primitives { pub use vybe_compiler::primitives::*; }
#[path="fixtures/packing_normalized_byte_before.rs"] mod before;
#[path="fixtures/packing_normalized_byte_candidate.rs"] mod candidate;
use vybe_runtime::{Chunk,Op,Value,VM};
fn byte(old:bool)->Chunk {let mut c=vec![Chunk::new("normalized_byte")];c[0].arity=1;c[0].param_count=1;c[0].local_count=1;if old{before::emit_pack_byte_from_f64_slot(&mut c,0,0,17)}else{candidate::emit_pack_byte_from_bounded_f64_slot(&mut c,0,0,17)}c[0].emit_op(Op::RETURN,17);c.remove(0)}
fn owner(leaf:Chunk)->Vec<Chunk>{let mut r=Chunk::new("<byte-owner>");vybe_compiler::primitives::functions::emit_ref_func(&mut r,1,0,17);r.emit_op(Op::RETURN,17);vec![r,leaf]}
fn vm()->VM{let mut v=VM::new();vybe_compiler::primitives::platforms::register_platforms_all(&mut v);v}
fn normalize(x:f64)->f64{if x>=0.0&&x<4294967296.0{x}else if x.abs()<f64::INFINITY{let n=x.trunc();n-(n/4294967296.0).floor()*4294967296.0}else{0.0}}
fn ops(c:&Chunk)->usize{let(mut at,mut count)=(0,0);while at<c.code.len(){let op=Op::from_code_at(&c.code,at);at+=4+op.operand_format().size_in(&c.code,at+4);count+=1;}count}
#[test] fn exact_emission_prefix_scratch_and_generic_contract(){let a=byte(true);let b=byte(false);assert_eq!(&a.code[..22],&b.code[..22],"same truncate/store/reload prefix and exact physical root write");assert_eq!(a.local_count,b.local_count);assert_eq!(a.imports,b.imports);assert_eq!(a.code.len()-b.code.len(),46);assert_eq!(ops(&a)-ops(&b),7);
 let mut live=vec![Chunk::new("normalized_byte")];live[0].arity=1;live[0].param_count=1;live[0].local_count=1;vybe_compiler::primitives::packing::emit_pack_byte_from_f64_slot(&mut live,0,0,17);live[0].emit_op(Op::RETURN,17);assert_eq!(live[0].code,a.code,"generic Lua/unbounded route unchanged");
 {let mut live=vec![Chunk::new("normalized_byte")];live[0].arity=1;live[0].param_count=1;live[0].local_count=1;vybe_compiler::primitives::packing::emit_pack_byte_from_bounded_f64_slot(&mut live,0,0,17);live[0].emit_op(Op::RETURN,17);assert_eq!(live[0].code,b.code);assert_eq!(live[0].local_count,b.local_count);}
 for endian in [false,true]{let(mut x,mut y)=(vec![Chunk::new("wide")],vec![Chunk::new("wide")]);x[0].local_count=1;y[0].local_count=1;before::emit_pack_u32_from_f64_slot(&mut x,0,0,if endian{before::Endian::Big}else{before::Endian::Little},17);candidate::emit_pack_u32_from_f64_slot(&mut y,0,0,if endian{candidate::Endian::Big}else{candidate::Endian::Little},17);assert_eq!(x[0].code,y[0].code);assert_eq!(x[0].imports,y[0].imports);assert_eq!(x[0].local_count,y[0].local_count);}
}
#[test] fn php_normalization_all_boundaries_tags_and_huge_finite(){let mut values=vec![0.0,-0.0,0.1,-0.1,1.9,-1.5,255.9,-255.9,256.0,-256.0,4294967295.9,4294967296.0,-4294967296.0,9007199254740992.0,-9007199254740992.0,f64::MAX,-f64::MAX,f64::MIN_POSITIVE,f64::from_bits(1),f64::NAN,f64::INFINITY,f64::NEG_INFINITY];for base in [256.0f64,4294967296.0,9007199254740992.0]{for bits in [base.to_bits()-1,base.to_bits(),base.to_bits()+1]{values.push(f64::from_bits(bits));values.push(-f64::from_bits(bits));}}
 let mut a=vm();let af=a.run(owner(byte(true))).unwrap();let mut b=vm();let bf=b.run(owner(byte(false))).unwrap();for x in values{let n=normalize(x);assert!(n>=0.0&&n<4294967296.0,"actual power-of-two normalization range {x:?}->{n:?}");let av=a.invoke(&af,&[Value::F64(n)]).unwrap();let bv=b.invoke(&bf,&[Value::F64(n)]).unwrap();assert_eq!(av,bv,"normalized {x:?}");let Value::String(s)=bv else{panic!("String ABI")};assert_eq!(s.encode_utf16().collect::<Vec<_>>(),vec![(n.trunc()as u32&255)as u16]);}
 for input in [Value::I32(255),Value::I64(4294967295),Value::F32(255.5),Value::F64(-0.0)]{assert_eq!(a.invoke(&af,&[input.clone()]).unwrap(),b.invoke(&bf,&[input]).unwrap());}
 for input in [Value::F64(f64::NAN),Value::F64(f64::INFINITY),Value::F64(f64::NEG_INFINITY)]{assert!(a.invoke(&af,&[input]).is_err(),"unchanged unbounded generic nonfinite trap");}
}
#[test] fn overwritten_object_root_releases_before_observer(){use std::sync::{Arc,Mutex,Weak};use vybe_runtime::value::Object;for old in [true,false]{let watched:Arc<Mutex<Option<Weak<Mutex<Object>>>>>=Arc::new(Mutex::new(None));let mut v=vm();let w=watched.clone();v.register_host_fn("test:byte","make",Box::new(move|_,_|{let o=vybe_runtime::heap::alloc(Object::new());*w.lock().unwrap()=Some(Arc::downgrade(&o));Value::Object(o)}));let w=watched.clone();v.register_host_fn("test:byte","released",Box::new(move|_,_|Value::Bool(w.lock().unwrap().as_ref().unwrap().upgrade().is_none())));
 let mut leaf=byte(old);let mut prefix=Chunk::new("prefix");let make=leaf.add_import("test:byte","make");prefix.emit_call(make,0,17);prefix.emit_op_u16(Op::LOCAL_SET,1,17);prefix.code.extend_from_slice(&leaf.code[..leaf.code.len()-4]);leaf.code=prefix.code;let observe=leaf.add_import("test:byte","released");leaf.emit_call(observe,0,17);leaf.emit_op(Op::RETURN,17);let f=v.run(owner(leaf)).unwrap();assert_eq!(v.invoke(&f,&[Value::F64(511.9)]).unwrap(),Value::Bool(true),"prior root released while byte result/frame still live");}}
#[test] fn strict_complete_native_kernels(){for old in [true,false]{wasmparser::Validator::new_with_features(wasmparser::WasmFeatures::all()).validate_all(&vybe_platform_wasm::write_wasm(&owner(byte(old)))).unwrap();}}
